<?php

declare(strict_types=1);

if (basename((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === basename(__FILE__)) { http_response_code(403); exit; }

function teacher_workspace_url(string $classId,string $projectId='',string $groupId='',array $extra=[]): string
{
    $params=['tab'=>'workspace','class'=>$classId];if($projectId!=='')$params['project']=$projectId;if($groupId!=='')$params['group']=$groupId;return 'teacher.php?'.http_build_query(array_replace($params,$extra));
}

function teacher_render_project_workspace(string $classId,string $projectId='',string $groupId=''): void
{
    $projects=array_values(array_filter((array)(project_catalog()[$classId]??[]),static fn($p):bool=>is_array($p)&&(string)($p['type']??'')==='group'));
    if($projectId==='')$projectId=(string)($projects[0]['id']??'');$project=project_find($classId,$projectId);if(!$project||(string)($project['type']??'')!=='group'){$project=$projects[0]??null;$projectId=(string)($project['id']??'');}
    $students=project_students_for_class($classId);$groups=$project?project_groups_for($classId,$projectId):[];$group=$groupId!==''?project_group_find($groupId):null;if($group&&((string)$group['class_id']!==$classId||(string)$group['project_id']!==$projectId))$group=null;
    ?>
    <section class="teacher-page-head"><div><div class="eyebrow">Project Workspace · týmová spolupráce</div><h1>Role, práce, QA a reflexe</h1><p>Učitel vidí konkrétní evidence a rizika. Systém nevytváří skryté „team score“ a peer feedback automaticky neurčuje známku.</p></div><?php if($project):?><a class="btn secondary" href="?tab=grade&class=<?=e($classId)?>&project=<?=e($projectId)?>">Společná projektová rubrika →</a><?php endif;?></section>
    <?php if(!$projects):?><div class="teacher-empty wide">Pro tuto třídu nejsou skupinové projekty.</div><?php return;endif;?>
    <nav class="teacher-project-tabs"><?php foreach($projects as $p):?><a class="<?=((string)$p['id']===$projectId)?'active':''?>" href="<?=e(teacher_workspace_url($classId,(string)$p['id']))?>"><span>Skupinový projekt</span><strong><?=e((string)$p['title'])?></strong></a><?php endforeach;?></nav>
    <?php $classInsights=project_class_collaboration_insights($classId);$themeLabels=['qa'=>'QA & testing','communication'=>'Komunikace','planning'=>'Plánování a termíny','ownership'=>'Odpovědnost','documentation'=>'Dokumentace','research'=>'Research']; ?>
    <section class="teacher-panel teacher-collaboration-insights"><div class="teacher-panel-head"><div><span>Collaboration Insights</span><h2>Rozvoj rolí napříč třídou</h2><p>Transparentní signály pro plánování dalšího projektu. Nejsou to známky ani automatické zásahy do týmů.</p></div><b><?= (int)$classInsights['published_role_evaluations'] ?> ověřených rolí</b></div><div class="teacher-role-distribution"><?php foreach(project_role_definitions() as $slug=>$def):?><article><i><?=e((string)$def['icon'])?></i><div><strong><?=e((string)$def['name'])?></strong><span><?= (int)($classInsights['role_counts'][$slug]??0) ?> zkušeností · <?= (int)($classInsights['strong_counts'][$slug]??0) ?> Strong+</span></div></article><?php endforeach;?></div><div class="teacher-insight-columns"><div><strong>Role rotation</strong><?php if($classInsights['rotation_candidates']):foreach(array_slice((array)$classInsights['rotation_candidates'],0,5) as $candidate):?><p><b><?=e((string)$candidate['label'])?></b> · <?=e((string)$candidate['text'])?></p><?php endforeach;else:?><p class="muted">Zatím bez výrazného opakování jediné role.</p><?php endif;?></div><div><strong>Nejčastější témata retrospektiv</strong><?php $shown=0;foreach((array)$classInsights['retro_themes'] as $theme=>$count):if((int)$count<1)continue;$shown++;?><p><b><?=e((string)($themeLabels[$theme]??$theme))?></b> · <?= (int)$count ?> zmínek</p><?php if($shown>=3)break;endforeach;if($shown===0):?><p class="muted">Zatím není dostatek retrospektivních dat.</p><?php endif;?></div></div></section>
    <?php if(!$group):?>
      <section class="teacher-workspace-summary">
        <?php if(!$groups):?><div class="teacher-empty wide">Pro tento projekt zatím není žádný uzamčený tým. Studenti jej mohou vytvořit přes Team Finder nebo učitel v záložce Týmy.</div><?php endif;?>
        <?php foreach($groups as $g):$h=project_workspace_health($classId,$projectId,(string)$g['id']);$attention=array_values(array_filter((array)$h['signals'],static fn($s)=>(string)($s['severity']??'')!=='ok'));?><article class="teacher-team-health <?= $attention?'attention':'ok' ?>"><header><div><span><?= $attention?'Potřebuje pozornost':'Bez zásadních signálů' ?></span><h2><?=e((string)$g['name'])?></h2><p><?=count((array)$g['member_keys'])?> členů · <?= (int)$h['tasks_done'] ?>/<?= (int)$h['tasks_total'] ?> úkolů hotovo</p></div><strong><?= (int)$h['completion'] ?> %</strong></header><div class="teacher-team-health-stats"><span><b><?= (int)$h['blocked'] ?></b> blokované</span><span><b><?= (int)$h['qa_open'] ?></b> QA otevřené</span><span><b><?=count((array)$h['missing_required_roles'])?></b> chybějící role</span><span><b><?= (int)$h['pulse']['help_requests'] ?></b> žádosti o pomoc</span></div><div class="teacher-health-signals"><?php foreach(array_slice((array)$h['signals'],0,3) as $s):?><span class="severity-<?=e((string)$s['severity'])?>"><?=e((string)$s['text'])?></span><?php endforeach;?></div><a class="btn primary small" href="<?=e(teacher_workspace_url($classId,$projectId,(string)$g['id']))?>">Otevřít tým</a></article><?php endforeach;?>
      </section>
    <?php return;endif;
    $groupId=(string)$group['id'];$health=project_workspace_health($classId,$projectId,$groupId);$coverage=$health['coverage'];$roles=project_roles_for_group($groupId);$tasks=project_tasks_for_group($groupId);$qa=project_qa_for_group($groupId);$checkins=project_checkins_for_group($groupId);$peer=project_peer_feedback_for_group($groupId);$retroStatus=project_retro_status($groupId);$evalStudent=(string)($_GET['student']??'');$evalRole=(string)($_GET['role']??'');$evalDef=project_role_definition($evalRole);$evalExisting=$evalStudent!==''?project_role_evaluation_find($groupId,$evalStudent,$evalRole):null;
    ?>
    <a class="teacher-back" href="<?=e(teacher_workspace_url($classId,$projectId))?>">← Všechny týmy</a>
    <section class="teacher-team-workspace-head"><div><div class="eyebrow"><?=e((string)$project['title'])?></div><h1><?=e((string)$group['name'])?></h1><p><?=count((array)$group['member_keys'])?> členů · role, odpovědnosti a evidence na jednom místě</p></div><div class="teacher-project-score"><strong><?= (int)$health['completion'] ?>%</strong><span>projektové práce</span></div></section>
    <div class="teacher-workspace-kpis"><article><span>Úkoly</span><strong><?= (int)$health['tasks_done'] ?> / <?= (int)$health['tasks_total'] ?></strong></article><article><span>Blokováno</span><strong><?= (int)$health['blocked'] ?></strong></article><article><span>QA otevřené</span><strong><?= (int)$health['qa_open'] ?></strong></article><article><span>Retrospektiva</span><strong><?=e($retroStatus==='open'?'OPEN':'CLOSED')?></strong></article></div>
