        <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Členové</span><h2>Individuální contribution evidence</h2><p>Role evaluation je oddělená od společné projektové rubriky.</p></div></div><div class="teacher-workspace-members"><?php foreach((array)$group['member_keys'] as $mk):if(!isset($students[$mk]))continue;$mrs=project_roles_for_student($groupId,(string)$mk);$mts=project_tasks_for_student($groupId,(string)$mk);$done=count(array_filter($mts,static fn($t)=>(string)($t['status']??'')==='done'));$ps=project_peer_summary($groupId,(string)$mk);$ev=project_role_evaluation_find($groupId,(string)$mk);?><article><div class="teacher-avatar"><?=e(u_substr((string)$students[$mk]['label'],0,1))?></div><div class="teacher-member-evidence"><strong><?=e((string)$students[$mk]['label'])?></strong><span><?= $mrs?e(implode(' + ',array_map(static fn($r)=>project_role_label((string)$r['role']),$mrs))):'bez potvrzené role' ?></span><small><?=$done?>/<?=count($mts)?> vlastních úkolů hotovo · <?=$ps['count']?> peer feedbacků</small><?php $contribSignals=project_student_contribution_signals($classId,$projectId,$groupId,(string)$mk);if($contribSignals):?><div class="teacher-member-signals"><?php foreach($contribSignals as $signal):?><span class="severity-<?=e((string)$signal['severity'])?>">Review recommended · <?=e((string)$signal['text'])?></span><?php endforeach;?></div><?php endif;?></div><div class="teacher-member-eval-state"><?php if($ev):?><b><?=number_format((float)$ev['score'],0)?> %</b><span><?=e((string)$ev['status'])?></span><?php endif;?></div><div class="teacher-member-actions"><?php if($mrs):?><div class="teacher-role-eval-links"><?php foreach($mrs as $rr):?><a class="btn secondary small" href="<?=e(teacher_workspace_url($classId,$projectId,$groupId,['student'=>$mk,'role'=>(string)$rr['role']]))?>">Hodnotit <?=e(project_role_label((string)$rr['role']))?></a><?php endforeach;?></div><?php endif;?><details><summary>Spravovat role</summary><?php if($mrs):?><div class="teacher-current-roles"><?php foreach($mrs as $rr):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_teacher_role_remove"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><input type="hidden" name="student_key" value="<?=e((string)$mk)?>"><input type="hidden" name="role" value="<?=e((string)$rr['role'])?>"><span><?=e(project_role_label((string)$rr['role']))?> · <?=e((string)$rr['role_type'])?></span><button class="link-button danger" type="submit">odebrat</button></form><?php endforeach;?></div><?php endif;?><form method="post" class="teacher-inline-role"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_teacher_role_assign"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><input type="hidden" name="student_key" value="<?=e((string)$mk)?>"><select name="role"><?php foreach(project_role_definitions() as $slug=>$def):?><option value="<?=e($slug)?>"><?=e((string)$def['name'])?></option><?php endforeach;?></select><select name="role_type"><option value="primary">primární</option><option value="secondary">support</option></select><button class="btn tertiary small">Přidat</button></form></details></div></article><?php endforeach;?></div></section>

        <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Práce</span><h2>Tasks & dependencies</h2></div></div><div class="teacher-workspace-task-table"><div class="head"><span>Úkol</span><span>Owner</span><span>Role</span><span>Stav</span><span>Komplexita</span></div><?php foreach($tasks as $t):?><div class="row status-<?=e((string)$t['status'])?>"><span><strong><?=e((string)$t['title'])?></strong><?php if((string)$t['status']==='blocked'):?><small><?=e((string)$t['blocked_reason'])?></small><?php endif;?></span><span><?=e(project_workspace_student_label($classId,(string)$t['owner_key']))?></span><span><?=e($t['role']?project_role_label((string)$t['role']):'—')?></span><span><?=e(project_workspace_task_status_label((string)$t['status']))?></span><span><?= (int)$t['complexity'] ?>/5</span></div><?php endforeach;?></div><?php if(!$tasks):?><div class="teacher-empty">Tým zatím nevytvořil žádné tasky.</div><?php endif;?></section>

        <section class="teacher-panel"><div class="teacher-panel-head"><div><span>QA</span><h2>Nálezy a ověření</h2></div></div><div class="teacher-qa-list"><?php foreach($qa as $q):?><article class="severity-<?=e((string)$q['severity'])?>"><div><strong><?=e((string)$q['title'])?></strong><span><?=e(project_workspace_severity_label((string)$q['severity']))?> · <?=e(project_workspace_qa_status_label((string)$q['status']))?></span><p><?=e((string)$q['description'])?></p></div><small><?=e(project_workspace_student_label($classId,(string)$q['created_by']))?><?php if($q['assigned_to']):?> → <?=e(project_workspace_student_label($classId,(string)$q['assigned_to']))?><?php endif;?></small></article><?php endforeach;?></div><?php if(!$qa):?><div class="teacher-empty">Zatím bez QA nálezů.</div><?php endif;?></section>

        <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Peer feedback</span><h2>Moderace a evidence spolupráce</h2><p>Student vidí agregaci. Učitel vidí autora kvůli bezpečnosti a případnému zneužití.</p></div></div><div class="teacher-peer-list"><?php foreach($peer as $pf):?><article class="status-<?=e((string)$pf['status'])?>"><header><strong><?=e(project_workspace_student_label($classId,(string)$pf['reviewer_key']))?> → <?=e(project_workspace_student_label($classId,(string)$pf['reviewee_key']))?></strong><span><?=e((string)$pf['status'])?></span></header><div class="teacher-peer-ratings"><?php foreach((array)$pf['ratings'] as $k=>$v):?><span><?=e((string)$k)?> <b><?= (int)$v ?>/5</b></span><?php endforeach;?></div><?php if($pf['praise']):?><p><b>+</b> <?=e((string)$pf['praise'])?></p><?php endif;?><?php if($pf['improve']):?><p><b>→</b> <?=e((string)$pf['improve'])?></p><?php endif;?><?php if((string)$pf['status']==='flagged'):?><form method="post" class="teacher-moderate"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_teacher_peer_moderate"><input type="hidden" name="feedback_id" value="<?=e((string)$pf['id'])?>"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><button class="btn secondary small" name="moderation" value="approved">Schválit</button><button class="btn tertiary small danger" name="moderation" value="hidden">Skrýt</button></form><?php endif;?></article><?php endforeach;?></div><?php if(!$peer):?><div class="teacher-empty">Peer feedback zatím nebyl odevzdaný.</div><?php endif;?></section>
      </main>
      <aside>
        <section class="teacher-panel"><div class="teacher-panel-head compact"><div><span>Retrospektiva</span><h3><?=e($retroStatus==='open'?'Otevřená':'Zavřená')?></h3></div></div><p><?=e($retroStatus==='open'?'Studenti mohou odevzdat sebereflexi, peer feedback a týmové Keep/Improve/Try.':'Otevřete reflexi ručně, nebo se studentům automaticky zpřístupní po dokončení většiny práce.')?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_teacher_retro"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><input type="hidden" name="retro_status" value="<?=$retroStatus==='open'?'closed':'open'?>"><button class="btn <?=$retroStatus==='open'?'secondary':'primary'?> wide" type="submit"><?=$retroStatus==='open'?'Zavřít retrospektivu':'Otevřít retrospektivu'?></button></form></section>
        <section class="teacher-panel"><div class="teacher-panel-head compact"><div><span>Team Pulse</span><h3>Poslední check-iny</h3></div></div><div class="teacher-checkin-list"><?php $latest=[];foreach($checkins as $ci){$k=(string)$ci['student_key'];if(!isset($latest[$k])||strcmp((string)$ci['updated_at'],(string)$latest[$k]['updated_at'])>0)$latest[$k]=$ci;}foreach($latest as $ci):?><article><strong><?=e(project_workspace_student_label($classId,(string)$ci['student_key']))?></strong><span><?=['green'=>'🟢 jde to','yellow'=>'🟡 potřebuje pomoc','red'=>'🔴 blokace'][(string)$ci['mood']]??'•'?></span><?php if($ci['help']):?><p><?=e((string)$ci['help'])?></p><?php endif;?><?php if((string)$ci['visibility']==='teacher'):?><small>🔒 pouze pro učitele</small><?php endif;?></article><?php endforeach;?></div><?php if(!$latest):?><div class="teacher-empty">Bez check-inů.</div><?php endif;?></section>
        <section class="teacher-panel"><div class="teacher-panel-head compact"><div><span>Retrospektiva</span><h3><?=count(project_self_retro_for_group($groupId))?> / <?=count((array)$group['member_keys'])?> sebereflexí</h3></div></div><?php $selfRows=project_self_retro_for_group($groupId);?><div class="teacher-mini-list"><?php foreach($selfRows as $r):?><article><strong><?=e(project_workspace_student_label($classId,(string)$r['student_key']))?></strong><span>✓ self reflection</span><small><?=e((string)$r['next_time'])?></small></article><?php endforeach;?></div></section>
      </aside>
    </div>

    <?php if($evalStudent!==''&&isset($students[$evalStudent])&&$evalDef):$rubric=(array)$evalDef['rubric'];$ev=$evalExisting; ?>
      <section class="teacher-panel teacher-role-evaluation" id="role-evaluation"><div class="teacher-panel-head"><div><span>Individual Role Evaluation</span><h2><?=e((string)$students[$evalStudent]['label'])?> · <?=e((string)$evalDef['name'])?></h2><p>Teacher evaluation je evidence. Peer feedback ani počet tasků se na skóre nepřevádí automaticky.</p></div><a class="text-link" href="<?=e(teacher_workspace_url($classId,$projectId,$groupId))?>">Zavřít</a></div>
      <form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_teacher_role_evaluation"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><input type="hidden" name="student_key" value="<?=e($evalStudent)?>"><input type="hidden" name="role" value="<?=e($evalRole)?>"><div class="teacher-role-rubric"><?php foreach($rubric as $key=>$criterion):$current=(string)($ev['criteria'][$key]??'competent');?><article><div><strong><?=e((string)$criterion['title'])?></strong><p><?=e((string)$criterion['description'])?></p></div><select name="criterion[<?=e((string)$key)?>]"><?php foreach(project_role_level_values() as $lv=>$points):?><option value="<?=e($lv)?>" <?=$current===$lv?'selected':''?>><?=e(project_role_level_label($lv))?> · <?=$points?>%</option><?php endforeach;?></select></article><?php endforeach;?></div><div class="teacher-feedback-grid"><label>Silné stránky<textarea name="strengths" rows="3"><?=e((string)($ev['strengths']??''))?></textarea></label><label>Další fokus<textarea name="next_focus" rows="3"><?=e((string)($ev['next_focus']??''))?></textarea></label></div><label>Souhrnný komentář<textarea name="teacher_comment" rows="4"><?=e((string)($ev['teacher_comment']??''))?></textarea></label><div class="teacher-eval-submit"><label>Stav<select name="status"><option value="draft" <?=((string)($ev['status']??'draft')==='draft'?'selected':'')?>>Koncept</option><option value="published" <?=((string)($ev['status']??'')==='published'?'selected':'')?>>Publikovat studentovi + Skill Evidence</option></select></label><button class="btn primary" type="submit">Uložit hodnocení role</button></div></form></section>
